# -*- coding: utf-8 -*-
"""English text of the dialogue lines — by string id from Module/ModuleData/Languages/RU/eq_*_rus.xml.

The Russian files are the source: the order, the groups and the substitutions live there. Here is only
the translation for each id; tools/make_dialogue.py builds the English files and stubs for the other
languages from this. Substitutions ({PLAYER.NAME}, {?PLAYER.GENDER}...{?}...{\\?}, [if:...]) must stay
the same as in the Russian string, otherwise the game shows nothing or breaks the gender choice.
"""

EN = {
    # ------------------------------------------------------------------ bandits
    "eq_surrender_1": "All right, all right, we give up! We just wanted to make friends... our way. Show a little kindness.",
    "eq_surrender_2": "Okay, okay! We surrender! Just don't call Fluttershy, she's got The Stare!",
    "eq_surrender_3": "We surrender! Pony promise — cross my heart and hope to fly, stick a cupcake in my eye!",
    "eq_surrender_4": "Fine, you win. Can we at least keep the cupcakes?",
    "eq_surrender_5": "We give up! Call it a friendship lesson — for us. We've learned it, honest.",
    "eq_surrender_6": "Don't hit us! We actually wanted to be Wonderbolts, but they wouldn't take us...",
    "eq_nosurrender_1": "Our friendship is stronger than your swords! You'll never take us alive![if:convo_angry][ib:aggressive]",
    "eq_nosurrender_2": "Surrender? Do we look like ponies who surrender? Well, maybe a little... But not today![if:convo_angry][ib:aggressive]",
    "eq_nosurrender_3": "Twenty percent cooler — and charge! Attack![if:convo_angry][ib:aggressive]",
    "eq_nosurrender_4": "You want our horseshoes? Come and take them![if:convo_angry][ib:aggressive]",
    "eq_nosurrender_5": "Never! We'll hold on like Applejack to the last apple![if:convo_angry][ib:aggressive]",
    "eq_nomercy_1": "So that's how it is? Fine — I'll show at least one of you what real friendship feels like![if:convo_angry][ib:aggressive]",
    "eq_nomercy_2": "And you call that harmony?! All right, then — here's a lesson you won't forget![if:convo_angry][ib:aggressive]",
    "eq_nomercy_3": "That's it! Somepony's about to get bucked so hard their cutie mark falls off![if:convo_angry][ib:aggressive]",
    "eq_nomercy_4": "No mercy? Then don't expect any cupcakes or greeting cards from us either![if:convo_angry][ib:aggressive]",
    "eq_leave_1": "Well, that's just fine! Friendly roads to you!",
    "eq_leave_2": "Thank you, kind pony! We're off... to find somepony easier.",
    "eq_leave_3": "You won't regret it! Probably. We'll send you a card. Maybe.",
    "eq_leave_4": "We're going, we're going! Not a word to anypony, okay? Especially the Royal Guard.",
    "eq_noleave_1": "Wait, wait... Where are you off to, friend? We're not done yet.",
    "eq_noleave_2": "Not so fast, Rainbow Dash! We haven't finished talking.",
    "eq_noleave_3": "Hey, hey, hey, the party's not over yet! Pinkie would be hurt.",
    "eq_noleave_4": "Leaving already? What about a parting gift? Your purse, for instance.",
    "eq_hideoutduel_1": "You! You scattered all my friends! Let's settle this fair — one on one, like old friend-enemies.",
    "eq_hideoutduel_2": "You wrecked my hideout and scared off my crew. Face me one on one — let's see whose cutie mark is tougher!",
    "eq_hideoutduel_3": "Not bad for a tourist. Now try me — no entourage, hoof to hoof.",
    "eq_hideoutduel_4": "You ruined our whole party! Want to finish it? One on one, then!",
    "eq_neutral_1": "Friendship is magic, traveler. Ours just bites. Keep moving.[if:convo_mocking_revenge]",
    "eq_neutral_2": "You have no idea how strong our friendship is. Want to feel it on your own hide?[if:convo_bared_teeth]",
    "eq_neutral_3": "We're having a friendship picnic here. Uninvited guests aren't welcome.",
    "eq_neutral_4": "Smile, traveler! The last one who didn't is still looking for his horseshoes.[if:convo_mocking_revenge]",
    "eq_neutral_5": "Love and tolerance, remember? We're still tolerating. Don't test us.[if:convo_angry]",
    "eq_neutral_6": "We're just a bunch of best friends... very hungry best friends.",
    "eq_neutral_7": "Touch one of us and you deal with all of us. That's the kind of friends we are.[if:convo_aggressive]",
    "eq_neutral_8": "Harmony is you going your way and us going ours. Let's do that.",
    "eq_neutral_9": "There are more of us than it looks. Behind that hill our friends are waiting — a lot of friends.",
    "eq_neutral_10": "What do you want? If you came for friendship — ours costs money.[if:convo_mocking_revenge]",
    "eq_neutral_11": "One more step and your cutie mark becomes a target.[if:convo_bared_teeth]",
    "eq_neutral_12": "We're not bandits, we're... cutie mark crusaders. Right now we're crusading for the 'robbed a traveler' mark.[if:convo_mocking_revenge]",
    "eq_neutral_13": "Careful! Our boss once ate an entire cake of Princess Celestia's. By himself. Without asking.",
    "eq_neutral_14": "Did you just walk out of the Everfree? Timberwolves say hello more politely.",
    "eq_neutral_15": "The Great and Powerful Trixie says: no autographs and no fights!",
    "eq_neutral_16": "We're counting pebbles for the Diamond Dogs. Don't interrupt, or we'll lose count and get upset.[if:convo_angry]",
    "eq_neutral_17": "Our orders: treat every stranger to cupcakes. Only our cupcakes are... special. Like Pinkie's on a dark day.[if:convo_bared_teeth]",
    "eq_neutral_18": "Stay back! We've got parasprites on a leash here, and they're hungry.",
    "eq_neutral_19": "Heard of the sonic rainboom? You're about to hear one right next to your ear.[if:convo_aggressive]",
    "eq_neutral_20": "Think Nightmare Moon is just a foal's tale? We'll show her to you in your nightmares.[if:convo_mocking_revenge]",
    "eq_neutral_21": "Leave while you can. Even an Ursa Minor doesn't mess with us.",
    "eq_neutral_22": "Hey! This is a private apple field. Well, it was private... until yesterday.",
    "eq_neutral_23": "Just passing through. Like Flim and Flam — only without the cider and with clubs.[if:convo_mocking_revenge]",
    "eq_neutral_24": "Be glad it's not Nightmare Night. We wouldn't be talking then.",
    "eq_robbery_threat_1": "Halt, traveler! Feel the power of our friendship! Or share your purse — friends share, after all.[if:convo_bared_teeth]",
    "eq_robbery_pay_1": "Now that's friendly! Show us what you've got.",
    "eq_robbery_done_1": "See how easy friendship is? Safe travels, pal!",
    "eq_robbery_fight_1": "Won't be friends the nice way? Then we'll be friends the hard way![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_2": "Hey, pony! We're collecting donations for the friendship fund. Contributions are mandatory.[if:convo_mocking_revenge]",
    "eq_robbery_pay_2": "Generosity is one of the Elements of Harmony. Let's see how generous you are.",
    "eq_robbery_done_2": "Now that's generosity! Rarity herself would be proud of you. Now scram.",
    "eq_robbery_fight_2": "Being stingy isn't friendly. We'll teach you that right now![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_3": "What a meeting! We were just looking for new friends. And their gold.[if:convo_bared_teeth]",
    "eq_robbery_pay_3": "Good pony. New friends always bring gifts.",
    "eq_robbery_done_3": "The best gift is a gift from a friend. Run along while we're feeling nice.",
    "eq_robbery_fight_3": "No gift, then? Then you get a friendship lesson — with a hoof![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_4": "Stop right there! Friendship is magic, and magic is expensive these days. Pay up or regret it.[if:convo_aggressive]",
    "eq_robbery_pay_4": "Sensible. Let's discuss the price of our friendship.",
    "eq_robbery_done_4": "A pleasure doing business with you. Until next time, friend!",
    "eq_robbery_fight_4": "Have it your way! Now you'll learn the true power of our friendship![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_5": "Gotcha! Don't worry, we're nice. Until you get greedy.[if:convo_mocking_revenge]",
    "eq_robbery_pay_5": "That's the spirit. Hand over whatever you've got in there.",
    "eq_robbery_done_5": "See? Everypony's still friends. Go on and spread the harmony.",
    "eq_robbery_fight_5": "Getting greedy after all... Friends, with me![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_6": "Not one step further! The law of friendship rules this road: what's yours is everypony's.[if:convo_aggressive]",
    "eq_robbery_pay_6": "That's right. Sharing is fun!",
    "eq_robbery_done_6": "Now we're real friends. Ride on.",
    "eq_robbery_fight_6": "Won't share? Then we'll take it ourselves — the whole friendly gang![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_7": "Smile, pal! This is a robbery, but a very friendly one.[if:convo_mocking_revenge]",
    "eq_robbery_pay_7": "Let's settle this peacefully, like real friends.",
    "eq_robbery_done_7": "Friendship wins! And you're free to go.",
    "eq_robbery_fight_7": "Fine, the friendly way didn't work. This is going to hurt![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_8": "Look, a lonely traveler. It's so sad being alone... Let us lighten your load.[if:convo_bared_teeth]",
    "eq_robbery_pay_8": "Then we have a deal. Show us that load.",
    "eq_robbery_done_8": "Walking's easier now, isn't it? Don't mention it, friend.",
    "eq_robbery_fight_8": "You asked for it. We're about to surround you with care — from every side![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_9": "Halt! The Flim Flam Brothers present: the Super Speedy Coin Collector 6000! Only one purse![if:convo_mocking_revenge]",
    "eq_robbery_pay_9": "Excellent choice, valued customer! Guaranteed — right up to the next bend in the road.",
    "eq_robbery_done_9": "Thank you for your purchase! Complaints accepted in Manehattan. Probably.",
    "eq_robbery_fight_9": "No refunds. Beatings, however, are included![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_10": "Aha! The Great and Powerful Trixie foretold it: today you part with your money![if:convo_bared_teeth]",
    "eq_robbery_pay_10": "A wise decision. The stars approve. So does Trixie.",
    "eq_robbery_done_10": "The show is over! You may keep your applause — but not your coins.",
    "eq_robbery_fight_10": "Don't believe in prophecy? Then watch the 'vanishing traveler' trick![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_11": "Stop! This is a Diamond Dog checkpoint. One shiny to pass. No shinies — then you dig.[if:convo_aggressive]",
    "eq_robbery_pay_11": "Shinies? Give them here, give them here! Dogs love shinies.",
    "eq_robbery_done_11": "Good shinies. Go on through while we sniff them.",
    "eq_robbery_fight_11": "No shinies — take a shovel! Or take a beating![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_12": "Don't move! We accidentally spilled cupcakes here, and there's a fine for every one you squash. You've squashed three already.[if:convo_mocking_revenge]",
    "eq_robbery_pay_12": "Now that's fair. Cupcakes paid for, no complaints.",
    "eq_robbery_done_12": "Enjoy! Just watch your hooves next time.",
    "eq_robbery_fight_12": "Won't pay for the cupcakes? Then you'll work them off — in bruises![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_13": "Gotcha, little pegasus... oops, I mean pony! A sonic rainboom won't save you — we've got nets strung up.[if:convo_bared_teeth]",
    "eq_robbery_pay_13": "Hold still and it'll be over faster than a good Wonderbolts flyby.",
    "eq_robbery_done_13": "Fly... I mean, walk. We took twenty percent of your coolness.",
    "eq_robbery_fight_13": "Want to see who's faster? We'll test your ribs![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_14": "Hush, traveler... Nightmare Moon has returned, and she demands tribute. Through us, that is.[if:convo_bared_teeth]",
    "eq_robbery_pay_14": "Good. The night is kind to those who pay.",
    "eq_robbery_done_14": "Sleep well. If you can.",
    "eq_robbery_fight_14": "Not afraid of the dark? It's about to get very dark![if:convo_angry][ib:aggressive]",
    "eq_robbery_threat_15": "Hey, farmer! This year's zap apple harvest is ours. Along with your money.[if:convo_aggressive]",
    "eq_robbery_pay_15": "Now that's neighborly. Granny Smith would approve. Probably.",
    "eq_robbery_done_15": "We'll mail you some zap apple jam. Maybe.",
    "eq_robbery_fight_15": "Won't hand over the harvest? Then we'll gather it ourselves — straight off your hide![if:convo_angry][ib:aggressive]",

    # ------------------------------------------------------------------ lords
    # The clan name already contains the word "House" (House of the Sun), so "of House {EQ_LORD_CLAN}"
    # gave "of House House of the Sun" — we write just "of {EQ_LORD_CLAN}"
    "eq_lord_meet_1": "Greetings, traveler. I am {LORD.NAME} of {EQ_LORD_CLAN}. I don't recognize your cutie mark — who might you be?",
    "eq_lord_meet_2": "A new face! I am {LORD.NAME}, and I serve {EQ_LORD_KINGDOM}. And you must be one of those they whisper about in the taverns?",
    "eq_lord_meet_3": "Hold on, no rush. I am {LORD.NAME}. Around here we introduce ourselves — even very busy ponies.",
    "eq_lord_meet_4": "Hello there! I am {LORD.NAME} of {EQ_LORD_CLAN}. Celestia teaches us: every stranger is a friend we haven't had tea with yet.",
    "eq_lord_meet_5": "Who has the wind blown in? I am {LORD.NAME}. Speak — who are you and what brings you here?[if:convo_thinking]",
    "eq_lord_greet_1": "Ah, {PLAYER.NAME}. What brings you to me?",
    "eq_lord_greet_2": "{PLAYER.NAME}! What news from Equus?",
    "eq_lord_greet_3": "You again, {PLAYER.NAME}. I hope it's business — my troops haven't been fed.",
    "eq_lord_greet_4": "Greetings, {PLAYER.NAME}. Speak, but keep it short: the sun won't raise itself. Though we do have a princess for that.",
    "eq_lord_greet_5": "{PLAYER.NAME}. Good to see you. Tea? No? To business, then.",
    "eq_lord_greet_6": "Hello, {PLAYER.NAME}. How may {EQ_LORD_CLAN} be of service?",
    "eq_lord_friend_1": "{PLAYER.NAME}, my friend! How glad I am to see you![if:convo_happy]",
    "eq_lord_friend_2": "Ha! {PLAYER.NAME}! Now this is a meeting! Pinkie would have thrown a party by now.[if:convo_happy]",
    "eq_lord_friend_3": "{PLAYER.NAME}! For you I always have time — and a slice of apple pie.[if:convo_happy]",
    "eq_lord_friend_4": "My good friend {PLAYER.NAME}! Tell me how I can help — {EQ_LORD_CLAN} remembers kindness.[if:convo_happy]",
    "eq_lord_cold_1": "{PLAYER.NAME}. I can't say I'm glad to see you.[if:convo_annoyed]",
    "eq_lord_cold_2": "You again. Make it quick — you give me split ends.[if:convo_annoyed]",
    "eq_lord_cold_3": "{PLAYER.NAME}... Love and tolerance, love and tolerance... What do you want?[if:convo_annoyed]",
    "eq_lord_cold_4": "Hm. If not for the laws of hospitality, this conversation wouldn't be happening.[if:convo_annoyed]",
    "eq_lord_attack_1": "{PLAYER.NAME}! In the name of {EQ_LORD_KINGDOM} — lay down your arms or prepare to fight![if:convo_angry][ib:aggressive]",
    "eq_lord_attack_2": "You chose the wrong side, {PLAYER.NAME}. Now you'll learn what {EQ_LORD_CLAN} is worth![if:convo_angry][ib:aggressive]",
    "eq_lord_attack_3": "Caught you! Surrender, {PLAYER.NAME}, and maybe a warm cell awaits you instead of cold ground.[if:convo_angry][ib:aggressive]",
    "eq_lord_attack_4": "There will be no harmony today, {PLAYER.NAME}. Only steel![if:convo_angry][ib:aggressive]",
    "eq_lord_attack_5": "For {EQ_LORD_KINGDOM}! Take them![if:convo_angry][ib:aggressive]",
    "eq_lord_short_1": "You again, {PLAYER.NAME}? We just saw each other...",
    "eq_lord_short_2": "{PLAYER.NAME}? Forget something?",
    "eq_lord_short_3": "Again? You're just like Pinkie — everywhere at once.",
    "eq_lord_short_4": "Yes, yes, {PLAYER.NAME}, I'm listening...",

    # ------------------------------------------------------------------ other
    "eq_caravan_own_1": "Boss! Wagons greased, apples unbruised. How can I help?",
    "eq_caravan_own_2": "Everything by the manifest, everything in place! Your orders?",
    "eq_caravan_own_3": "Good to see you! Want to see how much we've traded? Spoiler: a lot.",
    "eq_caravan_1": "Greetings, traveler! The caravan is bound for Manehattan, but we can spare a minute for a good pony.",
    "eq_caravan_2": "Whoa! Make way for the trade caravan! Oh, it's just you. How can we help?",
    "eq_caravan_3": "Good day! Cider, cloth, gems — everything but discounts. What do you need?",
    "eq_caravan_4": "Hello, traveler! If Flim and Flam sent you — we're not buying anything.",
    "eq_again_1": "You again? What else can we do for you?",
    "eq_again_2": "Oh, we meet again! Equus is as cramped as a pumpkin cart.",
    "eq_again_3": "Hello again! Forget something?",
    "eq_villager_1": "Good day, {?PLAYER.GENDER}madam{?}sir{\\?}! {VILLAGER_PARTY_EXPLANATION}. {VILLAGER_STATE}",
    "eq_villager_2": "Oh, hello! Don't startle us like that, we've got fragile goods in the cart. {VILLAGER_PARTY_EXPLANATION}. {VILLAGER_STATE}",
    "eq_villager_3": "Greetings! The sun is shining, the princesses are where they should be — a good day. {VILLAGER_PARTY_EXPLANATION}. {VILLAGER_STATE}",
    "eq_smith_1": "Good day, {?PLAYER.GENDER}madam{?}sir{\\?}! Horseshoes, swords, mane armor — how can I help?",
    "eq_smith_2": "Careful, it's hot! What are we forging today?",
    "eq_smith_3": "Ah, a customer! My hammer was getting bored. How can I help?",
    "eq_smith_4": "Hello! If you want lucky horseshoes, see the fortune teller. If you just want sturdy ones, see me.",
    "eq_prisoner_1": "Yes? What now?",
    "eq_prisoner_2": "Come to admire me? These chains don't suit me at all.",
    "eq_prisoner_3": "What do you want? If you brought a cupcake, speak up. If not, move along.",
    "eq_merc_single_1": "Need a sturdy pony in your company, {?PLAYER.GENDER}madam{?}sir{\\?}? For {GOLD_AMOUNT}{GOLD_ICON} my hoof is yours.",
    "eq_merc_single_2": "Looking for somepony to serve. Can't beat a dragon, but a timberwolf — easily. The price is {GOLD_AMOUNT}{GOLD_ICON}.",
    "eq_merc_single_3": "Hey, captain! I'd like some work. {GOLD_AMOUNT}{GOLD_ICON} and I'll follow you into the Everfree itself.",
    "eq_merc_ready_1": "Don't worry, I'll finish my cider and catch up.",
    "eq_merc_ready_2": "Coming! Just let me finish my cupcake — you can't abandon a cupcake.",
    "eq_merc_ready_3": "One second, saying goodbye to the tavernkeeper. We're best friends now.",
    "eq_alley_own_1": "Greetings, boss. {?SPEAKER.GENDER}Glad{?}Glad{\\?} to see you. The street is watched, nopony's complaining.",
    "eq_alley_own_2": "Here's the boss! Business is good, coins are jingling. How can I help?",
    "eq_alley_own_3": "All quiet, {?PLAYER.GENDER}madam{?}sir{\\?}. Even the guards don't drop by — we bring them cupcakes.",
    "eq_alley_attack_1": "Good thing you're here, {?PLAYER.GENDER}madam{?}sir{\\?}! Let's show them whose street this is!",
    "eq_alley_attack_2": "Just in time! These upstarts think the street is theirs. Shall we convince them otherwise?",
    "eq_alley_thug_1": "Hey, you! What are you doing here? This is our street.[if:convo_angry]",
    "eq_alley_thug_2": "Lost, {?PLAYER.GENDER}gorgeous{?}handsome{\\?}? Strangers aren't welcome here.[if:convo_mocking_revenge]",
    "eq_alley_thug_3": "Stop. There's a toll for this alley. Kidding. Or not.[if:convo_mocking_revenge]",
    "eq_bodyguard_1": "Don't talk to me. Talk to the boss.",
    "eq_bodyguard_2": "I just stand here and look scary. All talk goes to the boss.",
    "eq_arena_games_1": "Greetings! Here for the tournament, I bet? The prize is worth it — even Rainbow Dash would be jealous!",
    "eq_arena_games_2": "Welcome to the arena! Tournament's coming up — get your hooves and helmet ready.",
    "eq_arena_nogames_1": "Greetings, friend. No tournament right now, but you can always warm up in the arena.",
    "eq_arena_nogames_2": "No tournaments in sight — all the champions left for the Equestria Games. But you can practice.",
    "eq_arena_meet_1": "Good day! I can tell by your walk — you know which end of a sword to hold. How can I help?",
    "eq_arena_meet_2": "New here? No, I can see it in your eyes — a seasoned fighter. What brings you to the arena?",
    "eq_arena_again_1": "Greetings, {PLAYER.NAME}! Back on the sand?",
    "eq_arena_again_2": "{PLAYER.NAME}! The crowd remembers you. Going out again?",
    "eq_barber_1": "Care for a new mane, {?PLAYER.GENDER}madam{?}sir{\\?}? I can style it like Rarity's own!",
    "eq_barber_2": "Have a seat! Curls are in today, rainbows tomorrow. What shall we do?",
    "eq_barber_3": "The mane is a pony's face! Allow me to take care of your face.",
    "eq_barber_beggar_1": "Sorry, {?PLAYER.GENDER}poor thing{?}poor fellow{\\?}, I only cut for coin. But I can lend you a comb.",
    "eq_barber_beggar_2": "May the princesses keep you, but I don't cut for free.",
    "eq_boardgame_won_1": "Ah. A fine game. As good as Twilight against Celestia.",
    "eq_boardgame_won_2": "Great game! Next time I'll beat you.",
    "eq_gamehost_1": "Greetings, {?PLAYER.GENDER}wanderer{?}wanderer{\\?}! Know the game of {GAME_NAME}? I'm the best at it in these parts. Have a seat!",
    "eq_gamehost_2": "Hey, fancy a game of {GAME_NAME}? A favorite of the {CULTURE_NAME}{.g} folk. Loser buys the cider!",
    "eq_gamehost_noble_1": "Your grace! What an honor! Care for a game of {GAME_NAME}? It's the favorite pastime of the {CULTURE_NAME}{.g} folk.",
    "eq_gamehost_noble_2": "Your grace, a game of {GAME_NAME}? They say Princess Luna herself plays it at night.",
    "eq_hard_days_1": "Oh, hard times these days...",
    "eq_hard_days_2": "Ah, the cider used to be sweeter and the apples bigger...",
    "eq_town_liege_1": "May I be of service, your grace?",
    "eq_town_liege_2": "Your grace! Such an honor for us. How can I help?",
    "eq_town_child_1": "Sorry, {?PLAYER.GENDER}madam{?}sir{\\?}, I have to get home — Mom promised cupcakes. Anything else you need?",
    "eq_town_child_2": "Excuse me, my parents are waiting. Maybe you need something else?",
    "eq_town_tavern_1": "Good health to you! Can I help with anything?",
    "eq_town_tavern_2": "Cheers! The cider here is excellent. Can I point you anywhere?",
    "eq_town_busy_1": "Sorry, {?PLAYER.GENDER}madam{?}sir{\\?}, chores are waiting. Can I help with something?",
    "eq_town_busy_2": "In a hurry, in a hurry — I've got pies in the oven! What do you need?",
    "eq_beggar_1": "Buddy, let's stay out of each other's way: there aren't enough cupcakes to go around here as it is.",
    "eq_beggar_2": "Go somewhere else, pal. This is our spot — and our luck.",
    "eq_no_coins_1": "Nothing to give, sorry. May the princesses keep you.",
    "eq_no_coins_2": "I can barely scrape together enough for an apple myself... Good luck to you.",
    "eq_guard_no_coins_1": "Move along. I'm on duty and I've got no coins. Celestia keep you.",
    "eq_guard_no_coins_2": "No chatting on duty. Be on your way.",
    "eq_guard_beggar_1": "Get out of my sight, beggar![if:convo_angry]",
    "eq_guard_beggar_2": "Shoo! The Royal Guard doesn't give handouts![if:convo_angry]",
    "eq_guard_criminal_1": "There have been many complaints about you. Behave, or you'll be sent to the moon. Well, to the dungeon.[if:convo_mocking_revenge]",
    "eq_guard_criminal_2": "Ah, it's you. We're watching you. One wrong move and it's a cell for you.[if:convo_mocking_revenge]",
    "eq_guard_1": "Yes? What do you need?",
    "eq_guard_2": "Listening. Keep it short — I'm on duty.",
    "eq_guard_3": "In the name of the princesses — what do you want?",
    "eq_rescue_known_1": "{SALUTATION}... You came for me! Now that's friendship!",
    "eq_rescue_known_2": "{SALUTATION}! I knew you wouldn't leave me!",
    "eq_rescue_stranger_1": "I don't know you, but thank you! You're a true hero of Equus.",
    "eq_rescue_stranger_2": "Whoever you are — thank you! I owe you a cupcake.",
    "eq_hermit_1": "Oh, hello. Another noble pony chasing glory? What's it all for, when you could just watch the sunset...",
    "eq_hermit_2": "Hello. It's quiet here: no wars, no intrigue, just daisies and tea. Won't you stay?",
    "eq_tavernkeeper_1": "Welcome, {?PLAYER.GENDER}madam{?}sir{\\?}! The cider is fresh and the gossip is fresher. How can I help?",
    "eq_tavernkeeper_2": "Come in, traveler! Apple pie today, just like Granny Smith's. Almost.",
    "eq_tavernkeeper_3": "Greetings! The seat by the fire is free, and the rumors come at no charge. What'll it be?",
    "eq_tavernkeeper_4": "Hello! If you're looking for mercenaries, they're in the corner. If it's adventure, that's in the corner too.",
    "eq_maid_usual_1": "The usual?",
    "eq_maid_usual_2": "Cider again? Coming right up!",
    "eq_maid_drink_1": "Enjoying the fare, {?PLAYER.GENDER}madam{?}sir{\\?}?",
    "eq_maid_drink_2": "Everything tasty? Pinkie says our cupcakes are the second best in Equus!",
    "eq_ransom_again_1": "Greetings. Got prisoners? I'll buy at a fair price.",
    "eq_ransom_again_2": "Ah, you again. Brought prisoners? Show me.",
    "eq_ransom_1": "Greetings, {?PLAYER.GENDER}madam{?}sir{\\?}. You look like you know how to fight. Got a minute? We may have a common interest.",
    "eq_ransom_2": "Psst... You look like somepony who takes prisoners. I have a business proposal for you.",
    "eq_ransom_noble_1": "What an honor, {?PLAYER.GENDER}my lady{?}my lord{\\?}. A moment? I can offer you a valuable service.",
    "eq_ransom_noble_2": "Your grace! Prisoners are a burden, and I happen to relieve burdens. For gold, naturally.",
    "eq_trader_friend_1": "Ah, a {?PLAYER.GENDER}friend{?}friend{\\?} of my friends! Special prices for you. How can I help?",
    "eq_trader_friend_2": "Friends of our friends are our friends! What are we buying?",
    "eq_trader_1": "Welcome, {?PLAYER.GENDER}my lady{?}my lord{\\?}! The best goods in Equus, I swear on my cutie mark!",
    "eq_trader_2": "Come in, have a look! All fresh, all honest, almost like Applejack's.",
    "eq_trader_3": "Hello! Buying, selling, or just admiring?",
    "eq_trader_beggar_1": "Listen, {?PLAYER.GENDER}good pony{?}good pony{\\?}, times are hard, but you're scaring off all my customers.",
    "eq_trader_beggar_2": "Move along, no handouts here. You're scaring the customers.",
    "eq_workshop_own_1": "Hello, boss! Come to check how business is going?",
    "eq_workshop_own_2": "Boss! Work is boiling, hooves aren't resting.",
    "eq_workshop_1": "Well... How can I help, {?PLAYER.GENDER}madam{?}sir{\\?}?",
    "eq_workshop_2": "Good day! Lots of work, but there's a minute for you.",
    "eq_workshop_smithy_1": "Hot in here, isn't it, {?PLAYER.GENDER}madam{?}sir{\\?}? I need to get back to the anvil. How can I help?",
    "eq_workshop_smithy_2": "Mind the sparks! Horseshoes won't forge themselves. What do you need?",
    "eq_workshop_tannery_1": "Sorry about the smell, {?PLAYER.GENDER}madam{?}sir{\\?}. A tannery is a tannery. How can I help?",
    "eq_workshop_tannery_2": "Phew! Don't wrinkle your nose, you'll get used to it. How can I be of use?",
    "eq_workshop_pottery_1": "I hope the smoke doesn't bother you, {?PLAYER.GENDER}madam{?}sir{\\?}. The kiln has to be hot. How can I help?",
    "eq_workshop_pottery_2": "Careful, fresh pots! You break it, you buy it. Kidding. Mostly.",
    "eq_workshop_brewery_1": "I have a minute, {?PLAYER.GENDER}madam{?}sir{\\?}. Time to check the fresh cider. How can I help?",
    "eq_workshop_brewery_2": "Care to try the new cider? No? Then how can I help?",
    "eq_workshop_loom_1": "I have a minute, {?PLAYER.GENDER}madam{?}sir{\\?}, the loom is waiting. How can I help?",
    "eq_workshop_loom_2": "This cloth was ordered by Rarity herself! Well, almost herself. What do you need?",
    "eq_workshop_press_1": "Careful, {?PLAYER.GENDER}madam{?}sir{\\?}, don't put a hoof under the press! How can I help?",
    "eq_workshop_press_2": "Pressing oil, pressing juice! What brings you to us?",
    "eq_workshop_wood_1": "Pay no mind to the sawdust, {?PLAYER.GENDER}madam{?}sir{\\?}. How can I help?",
    "eq_workshop_wood_2": "Knock knock! That's not a woodpecker, that's me. How can I help?",
    "eq_notable_meet_1": "Greetings, traveler. I am {LORD.NAME}, everypony here knows me. And who might you be?",
    "eq_notable_meet_2": "A new face in {EQ_SETTLEMENT}! I am {LORD.NAME}. How can I be of use?",
    "eq_notable_greet_1": "Ah, {PLAYER.NAME}! Good to see you. What's new?",
    "eq_notable_greet_2": "{PLAYER.NAME}, hello. How can I help?",
    "eq_headman_meet_1": "Welcome to {EQ_SETTLEMENT}! I am {LORD.NAME}, the headman. A fine harvest this year — Applejack herself would approve.",
    "eq_headman_meet_2": "Hello, traveler. I am {LORD.NAME}, I look after the village. What brings you here?",
    "eq_headman_greet_1": "{PLAYER.NAME}! Come in, the pie has just come out of the oven.",
    "eq_headman_greet_2": "Ah, {PLAYER.NAME}. How are things in the wide world? Here it's the same as ever: we sow, we plow, we drink tea.",
    "eq_merchant_meet_1": "Greetings! {LORD.NAME}, merchant. If anything is sold in {EQ_SETTLEMENT}, it goes through me.",
    "eq_merchant_meet_2": "A new customer? Wonderful! I am {LORD.NAME}. Friendship is friendship, but trade goes by receipt.",
    "eq_merchant_greet_1": "{PLAYER.NAME}! Good to see you. Got a profitable deal?",
    "eq_merchant_greet_2": "Ah, {PLAYER.NAME}! Prices keep rising, and you keep looking just as good.",
    "eq_artisan_meet_1": "Hello! I am {LORD.NAME}, a craftspony. My work is praised even in Canterlot.",
    "eq_artisan_meet_2": "Careful, fresh varnish! I am {LORD.NAME}. How can I help?",
    "eq_artisan_greet_1": "{PLAYER.NAME}! Stop by the workshop — I have a new piece.",
    "eq_artisan_greet_2": "Hi, {PLAYER.NAME}. Hooves are busy, but ears are free — go ahead.",
    "eq_gangleader_meet_1": "Well, well. A new face. I am {LORD.NAME}, and every dark alley in {EQ_SETTLEMENT} is mine. What do you want?[if:convo_mocking_revenge]",
    "eq_gangleader_meet_2": "The name's {LORD.NAME}. Around here ponies are my friends — if they want to sleep soundly.[if:convo_mocking_revenge]",
    "eq_gangleader_greet_1": "{PLAYER.NAME}. You again. I hope it's business.[if:convo_mocking_revenge]",
    "eq_gangleader_greet_2": "Ah, {PLAYER.NAME}. Keep your voice down — the walls have ears, and the ears have my boys.",
    "eq_preacher_meet_1": "Peace be with you, traveler. I am {LORD.NAME}. The Sun and the Moon watch over this town.",
    "eq_preacher_meet_2": "Welcome. I am {LORD.NAME}, and I teach harmony. Would you like to hear about friendship?",
    "eq_preacher_greet_1": "May Celestia's sun shine upon you, {PLAYER.NAME}.",
    "eq_preacher_greet_2": "{PLAYER.NAME}! Luna saw you in a dream. A good sign.",
    "eq_ruralnotable_meet_1": "Welcome to our lands! I am {LORD.NAME}. The fields here are mine, and so are the apples.",
    "eq_ruralnotable_meet_2": "Hello! {LORD.NAME}, at your service. A big estate, many cares — tell me what brings you.",
    "eq_ruralnotable_greet_1": "{PLAYER.NAME}! Good to see you. Perhaps you'll drop by the fair?",
    "eq_ruralnotable_greet_2": "Ah, {PLAYER.NAME}. The harvest is ripening — the perfect time for business.",
    "eq_wanderer_meet_1": "Hey there! I am {LORD.NAME}. I see you like the long roads too. Have a seat?",
    "eq_wanderer_meet_2": "Hello, traveler. {LORD.NAME}, adventurer. I have a story — want to hear it?",
    "eq_wanderer_meet_3": "Wow, a real commander's bearing! I am {LORD.NAME}. Wouldn't you be looking for a reliable pony for your company?",
    "eq_wanderer_greet_1": "{PLAYER.NAME}! What brings you here?",
    "eq_wanderer_greet_2": "At your command, captain!",
    "eq_wanderer_greet_3": "{PLAYER.NAME}, I'm ready. Where are we going?",
}
